// Consolida feriados nacionais (BrasilAPI) + feriados fixos de contingência + feriados municipais/estaduais configurados
// e valida se a data de execução de hoje (ou data_simulacao_iso) é um dia útil.
const config = $('02. Parâmetros Globais').first().json;
const feriadosApi = $input.all().map(i => i.json?.date).filter(Boolean);
const feriadosLocais = Array.isArray(config.feriados_municipais_estaduais)
  ? config.feriados_municipais_estaduais
  : [];

const dataSP = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());
const dataSimulada = String(config.data_simulacao_iso || '').trim().slice(0, 10);
const dataHojeISO = /^\d{4}-\d{2}-\d{2}$/.test(dataSimulada) ? dataSimulada : dataSP;

const [yRef, mRef, dRef] = dataHojeISO.split('-').map(Number);
// Fallback de feriados nacionais fixos (caso a BrasilAPI sofra instabilidade pontual)
const sufixosFeriadosFixos = ['01-01', '04-21', '05-01', '09-07', '10-12', '11-02', '11-15', '11-20', '12-25'];
const feriadosFixosFallback = [
  ...sufixosFeriadosFixos.map(s => `${yRef}-${s}`),
  ...sufixosFeriadosFixos.map(s => `${yRef + 1}-${s}`)
];
const setFeriados = new Set([...feriadosApi, ...feriadosLocais, ...feriadosFixosFallback]);

const dtRef = new Date(Date.UTC(yRef, mRef - 1, dRef));
const diaSemana = dtRef.getUTCDay(); // 0 = Dom, 6 = Sab
const ehFimDeSemana = diaSemana === 0 || diaSemana === 6;
const ehFeriadoHoje = setFeriados.has(dataHojeISO);
const ehDiaUtilHoje = !ehFimDeSemana && !ehFeriadoHoje;

return [
  {
    json: {
      data_execucao_iso: dataHojeISO,
      eh_dia_util_hoje: ehDiaUtilHoje,
      motivo_bloqueio_dia: !ehDiaUtilHoje
        ? (ehFeriadoHoje ? 'FERIADO' : 'FIM_DE_SEMANA')
        : null,
      lista_feriados: Array.from(setFeriados),
      config
    }
  }
];

// ============================================================================
// MOTOR UNIFICADO DE REGRAS DE NEGÓCIO:
// 1. Desempacota o array `rows` retornado pelo nó Oracle (`Oracle_ERP_Read`).
// 2. Lê o histórico de controle vindo de "AUTOMATION"."AVIS_COBR" (`PostgreSQL_Main`).
// 3. Filtra todos os lançamentos (D e C):
//    - VLAB_REC != 0 (VLAB_REC já é o valor em aberto do título; VLOR_REC é o valor original)
//    - CODI_TDO IN (101, 102, 103)
//    - CODI_TCO NOT IN (10, 20, 30, 40)
//    - COD1_PES != 999
//    - Prazo (VENC_REC - DATA_CBR) > 15 dias (aplicado SOMENTE aos Débitos 'D')
// 4. Soma todos os Créditos (TIPO_TDO = 'C') em aberto da carteira do cliente.
// 5. Agrupa os Débitos (TIPO_TDO = 'D') do cliente por Data de Vencimento (VENC_REC)
//    em ordem cronológica crescente (FIFO).
// 6. Abate o Crédito (C) cronologicamente:
//    - Primeiro no vencimento mais próximo (ex: D-5) e só o crédito que sobrar
//      abate os vencimentos seguintes (ex: D-10).
//    - Se o Saldo Resultante do vencimento for <= 0 (Saldo Credor C), NÃO notifica.
//    - Se o Saldo Resultante do vencimento for > 0 (Saldo Devedor D) e a data de
//      notificação (D-10 ou D-5 antecipada para dia útil anterior) for HOJE (ou estiver
//      em Repescagem Automática de PENDENTE / SEM_WHATSAPP / NAO_ENTREGUE),
//      gera a mensagem única consolidada com o Saldo Resultante!
// 7. Higienização e Seleção Inteligente de Telefone (TEL1_TRA, TEL2_TRA, CFO1_TRA):
//    - Remove zeros antes do DDD (ex: 011 -> 11).
//    - Prioriza: 1º Celular 9 dígitos nativo (XX 9XXXX-XXXX) -> 2º Celular 8 dígitos
//      (convertido para 9 dígitos) -> 3º Fixo (8 dígitos iniciados em 2-5).
//    - Desempate dentro da mesma categoria pela ordem das colunas: TEL1_TRA > TEL2_TRA > CFO1_TRA.
//    - Retorna APENAS 1 número para envio na Z-API.
// ============================================================================

const contextoCalendario = $('04. Validar Calendário').first().json;
const dataHojeISO = contextoCalendario.data_execucao_iso;
const setFeriados = new Set(contextoCalendario.lista_feriados || []);
const config = contextoCalendario.config;
const modoTesteForcarJanela = Boolean(config.modo_teste_forcar_janela);

const lancamentosNode = $('06. Extrair Títulos').all();
const lancamentosRaw = lancamentosNode.flatMap(i => Array.isArray(i.json?.rows) ? i.json.rows : [i.json]);

const historicoNode = $input.all();
const historicoRaw = historicoNode.flatMap(i => Array.isArray(i.json?.rows) ? i.json.rows : [i.json]);

const docsPermitidos = new Set((config.codi_tdo_permitidos || [101, 102, 103]).map(Number));
const cobrancasExcluidas = new Set((config.codi_tco_excluidos || [10, 20, 30, 40]).map(Number));
const vendedoresExcluidos = new Set((config.cod1_pes_excluidos || [999]).map(Number));
const prazoMinimoExclusao = Number(config.prazo_minimo_exclusao_dias ?? 15);

function parseISODateUTC(isoStr) {
  const clean = String(isoStr).slice(0, 10);
  const [y, m, d] = clean.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}

function formatISODateUTC(dateObj) {
  const y = dateObj.getUTCFullYear();
  const m = String(dateObj.getUTCMonth() + 1).padStart(2, '0');
  const d = String(dateObj.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function addDaysUTC(dateObj, days) {
  const copy = new Date(dateObj.getTime());
  copy.setUTCDate(copy.getUTCDate() + days);
  return copy;
}

function diffDaysUTC(dateEnd, dateStart) {
  const msPerDay = 1000 * 60 * 60 * 24;
  return Math.round((dateEnd.getTime() - dateStart.getTime()) / msPerDay);
}

// Se cair em sábado (6), domingo (0) ou feriado, retrocede para o último dia útil anterior
function ajustarParaDiaUtilAnterior(dateObj) {
  let cursor = new Date(dateObj.getTime());
  while (true) {
    const iso = formatISODateUTC(cursor);
    const dow = cursor.getUTCDay();
    const ehFimSemana = dow === 0 || dow === 6;
    const ehFeriado = setFeriados.has(iso);
    if (!ehFimSemana && !ehFeriado) {
      return iso;
    }
    cursor = addDaysUTC(cursor, -1);
  }
}

// Histórico em "AUTOMATION"."AVIS_COBR" para:
// 1) Controle de idempotência (ENVIADO / ENVIADA)
// 2) Repescagem automática (PENDENTE / SEM_WHATSAPP / NAO_ENTREGUE / FALHA_TELEFONE)
// 3) Detecção de prorrogação de vencimento
const chavesJaEnviadas = new Set();
const chavesParaRepescagem = new Map();
const ultimoVencimentoPorClienteEtapa = new Map();
const statusElegiveisRepescagem = new Set(['PENDENTE', 'SEM_WHATSAPP', 'NAO_ENTREGUE', 'FALHA_TELEFONE']);

for (const h of historicoRaw) {
  if (!h) continue;
  const statusEnv = String(h?.STAT_COBR ?? h?.stat_cobr ?? h?.status_envio ?? h?.STATUS_ENVIO ?? '').trim().toUpperCase();
  const chaveIdemp = h?.CHAV_COBR ?? h?.chav_cobr ?? h?.chave_idempotencia ?? h?.CHAVE_IDEMPOTENCIA;
  const codCliHist = h?.CLIE_COBR ?? h?.clie_cobr ?? h?.codi_tra ?? h?.CODI_TRA;
  const etapaHist = h?.ETAP_COBR ?? h?.etap_cobr ?? h?.etapa_notificacao ?? h?.ETAPA_NOTIFICACAO;
  const dataVencHist = String(h?.VENC_COBR ?? h?.venc_cobr ?? h?.venc_rec ?? h?.VENC_REC ?? '').slice(0, 10);

  if (statusEnv === 'ENVIADO' || statusEnv === 'ENVIADA') {
    if (chaveIdemp) chavesJaEnviadas.add(String(chaveIdemp));
    if (codCliHist && etapaHist && dataVencHist) {
      ultimoVencimentoPorClienteEtapa.set(`${codCliHist}_${etapaHist}`, dataVencHist);
    }
  } else if (statusElegiveisRepescagem.has(statusEnv) && chaveIdemp) {
    chavesParaRepescagem.set(String(chaveIdemp), {
      stat_cobr: statusEnv,
      tent_cobr: Number(h?.TENT_COBR ?? h?.tent_cobr ?? 1),
      dtnt_cobr: String(h?.DTNT_COBR ?? h?.dtnt_cobr ?? '').slice(0, 10),
      dtne_cobr: String(h?.DTNE_COBR ?? h?.dtne_cobr ?? '').slice(0, 10)
    });
  }
}

// 1. Organizar carteira por Cliente (CODI_TRA)
const carteiraPorCliente = new Map();

for (const raw of lancamentosRaw) {
  if (!raw) continue;

  const codiTra = raw.CODI_TRA ?? raw.codi_tra;
  const razaTra = String(raw.RAZA_TRA ?? raw.raza_tra ?? '').trim();
  const codiEmp = raw.CODI_EMP ?? raw.codi_emp ?? null;
  const tel1Tra = String(raw.TEL1_TRA ?? raw.tel1_tra ?? '').trim();
  const tel2Tra = String(raw.TEL2_TRA ?? raw.tel2_tra ?? '').trim();
  const cfo1Tra = String(raw.CFO1_TRA ?? raw.cfo1_tra ?? '').trim();
  const codiTdo = Number(raw.CODI_TDO ?? raw.codi_tdo);
  const tipoTdo = String(raw.TIPO_TDO ?? raw.tipo_tdo ?? '').trim().toUpperCase();
  const codiTco = Number(raw.CODI_TCO ?? raw.codi_tco);
  const cod1Pes = Number(raw.COD1_PES ?? raw.cod1_pes ?? 0);
  const dataCbrRaw = raw.DATA_CBR ?? raw.data_cbr;
  const vencRecRaw = raw.VENC_REC ?? raw.venc_rec;

  // VLAB_REC já é o saldo em aberto do título; VLOR_REC é apenas o valor original
  const vlabRec = Number(raw.VLAB_REC ?? raw.vlab_rec ?? raw.SALDO_ABERTO ?? raw.saldo_aberto ?? 0);
  const saldoAberto = Math.abs(vlabRec);

  if (!codiTra || !vencRecRaw || !dataCbrRaw) continue;

  // Defesa em profundidade das regras de negócio
  if (saldoAberto <= 0) continue;
  if (!docsPermitidos.has(codiTdo)) continue;
  if (cobrancasExcluidas.has(codiTco)) continue;
  if (vendedoresExcluidos.has(cod1Pes)) continue;

  const dtEmissao = parseISODateUTC(dataCbrRaw);
  const dtVencimento = parseISODateUTC(vencRecRaw);
  const prazoVendaDias = diffDaysUTC(dtVencimento, dtEmissao);

  // Filtro dos 15 dias aplica-se SOMENTE aos Débitos (TIPO_TDO = 'D')
  if (tipoTdo === 'D' && prazoVendaDias <= prazoMinimoExclusao) continue;

  const chaveCli = String(codiTra);
  if (!carteiraPorCliente.has(chaveCli)) {
    carteiraPorCliente.set(chaveCli, {
      codi_tra: codiTra,
      raza_tra: razaTra,
      codi_emp: codiEmp,
      tel1_tra: tel1Tra,
      tel2_tra: tel2Tra,
      cfo1_tra: cfo1Tra,
      total_credito_c: 0,
      total_debito_d: 0,
      vencimentosMap: new Map()
    });
  }

  const cli = carteiraPorCliente.get(chaveCli);
  if (!cli.raza_tra && razaTra) cli.raza_tra = razaTra;
  if ((cli.codi_emp === null || cli.codi_emp === undefined || cli.codi_emp === '') && codiEmp !== null && codiEmp !== undefined) {
    cli.codi_emp = codiEmp;
  }
  if (!cli.tel1_tra && tel1Tra) cli.tel1_tra = tel1Tra;
  if (!cli.tel2_tra && tel2Tra) cli.tel2_tra = tel2Tra;
  if (!cli.cfo1_tra && cfo1Tra) cli.cfo1_tra = cfo1Tra;

  const vencISO = formatISODateUTC(dtVencimento);

  if (tipoTdo === 'C') {
    cli.total_credito_c = Number((cli.total_credito_c + saldoAberto).toFixed(2));
  } else if (tipoTdo === 'D') {
    cli.total_debito_d = Number((cli.total_debito_d + saldoAberto).toFixed(2));
    if (!cli.vencimentosMap.has(vencISO)) {
      cli.vencimentosMap.set(vencISO, {
        venc_rec_iso: vencISO,
        dt_vencimento: dtVencimento,
        valor_debito_bruto: 0,
        quantidade_titulos: 0
      });
    }
    const grpVenc = cli.vencimentosMap.get(vencISO);
    grpVenc.valor_debito_bruto = Number((grpVenc.valor_debito_bruto + saldoAberto).toFixed(2));
    grpVenc.quantidade_titulos += 1;
  }
}

function formatarMoedaBR(valor) {
  return Number(valor).toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function formatarDataBR(isoDate) {
  const [y, m, d] = String(isoDate).slice(0, 10).split('-');
  return `${d}/${m}/${y}`;
}

// Avalia um trecho de telefone individual e classifica pela regra Anatel:
// - Tier 1: Celular 9 dígitos nativo (XX 9XXXX-XXXX)
// - Tier 2: Celular 8 dígitos sem o 9 (XX [6-9]XXX-XXXX -> padronizado com 9 após o DDD)
// - Tier 3: Telefone Fixo 8 dígitos (XX [2-5]XXX-XXXX)
// - Tier 99: Inválido (ex: sem DDD, dígitos insuficientes/excedentes)
function analisarCandidatoTelefone(trechoBruto, ordemColuna, indiceTrecho) {
  const original = String(trechoBruto || '').trim();
  let digitos = original.replace(/\D/g, '');
  if (!digitos) return null;

  // Remove zeros à esquerda (ex: 011900000000 ou (01) 19000-0000 -> 1190000000)
  digitos = digitos.replace(/^0+/, '');

  // Se já vier com DDI 55 (ex: 5511900000000, 551190000000 ou 55011900000000), isola o número nacional
  if (digitos.startsWith('550') && digitos.length >= 13) {
    digitos = digitos.slice(2).replace(/^0+/, '');
  } else if (digitos.startsWith('55') && (digitos.length === 12 || digitos.length === 13)) {
    digitos = digitos.slice(2);
  }

  // Caso ainda reste zero à esquerda após remover DDI
  digitos = digitos.replace(/^0+/, '');

  if (digitos.length < 10 || digitos.length > 11) {
    return {
      valido: false,
      tier: 99,
      ordemColuna,
      indiceTrecho,
      original,
      e164: digitos,
      motivo: 'FORMATO_TEL1_TRA_INVALIDO'
    };
  }

  const ddd = Number(digitos.slice(0, 2));
  const dddStr = digitos.slice(0, 2);
  const numeroLocal = digitos.slice(2);

  // DDDs válidos no Brasil vão de 11 a 99 e nunca terminam em 0
  if (ddd < 11 || ddd > 99 || ddd % 10 === 0) {
    return {
      valido: false,
      tier: 99,
      ordemColuna,
      indiceTrecho,
      original,
      e164: digitos,
      motivo: 'FORMATO_TEL1_TRA_INVALIDO'
    };
  }

  // Caso 1: 11 dígitos nacionais (DDD + 9 dígitos locais) -> deve iniciar com 9 (XX 9XXXX-XXXX)
  if (numeroLocal.length === 9) {
    if (numeroLocal[0] === '9') {
      return {
        valido: true,
        tier: 1, // Prioridade 1: Celular 9 dígitos nativo (XX 9XXXX-XXXX)
        ordemColuna,
        indiceTrecho,
        original,
        e164: `55${dddStr}${numeroLocal}`,
        motivo: null
      };
    }
    return {
      valido: false,
      tier: 99,
      ordemColuna,
      indiceTrecho,
      original,
      e164: `55${dddStr}${numeroLocal}`,
      motivo: 'FORMATO_TEL1_TRA_INVALIDO'
    };
  }

  // Caso 2: 10 dígitos nacionais (DDD + 8 dígitos locais)
  const primeiroDigitoLocal = Number(numeroLocal[0]);

  // Subcaso 2A: Celular de 8 dígitos sem o 9 na frente (inicia com 6, 7, 8 ou 9)
  if (primeiroDigitoLocal >= 6 && primeiroDigitoLocal <= 9) {
    return {
      valido: true,
      tier: 2, // Prioridade 2: Celular 8 dígitos convertido para XX 9XXXX-XXXX
      ordemColuna,
      indiceTrecho,
      original,
      e164: `55${dddStr}9${numeroLocal}`,
      motivo: null
    };
  }

  // Subcaso 2B: Telefone fixo de 8 dígitos (inicia com 2, 3, 4 ou 5)
  if (primeiroDigitoLocal >= 2 && primeiroDigitoLocal <= 5) {
    return {
      valido: true,
      tier: 3, // Prioridade 3: Telefone Fixo (nunca adiciona 9)
      ordemColuna,
      indiceTrecho,
      original,
      e164: `55${dddStr}${numeroLocal}`,
      motivo: null
    };
  }

  return {
    valido: false,
    tier: 99,
    ordemColuna,
    indiceTrecho,
    original,
    e164: `55${dddStr}${numeroLocal}`,
    motivo: 'FORMATO_TEL1_TRA_INVALIDO'
  };
}

// Seleciona APENAS 1 número entre TEL1_TRA (P1), TEL2_TRA (P2) e CFO1_TRA (P3):
// Prioridade (A): Tier 1 (Celular 9 dígitos nativo) > Tier 2 (Celular 8 dígitos) > Tier 3 (Fixo),
// desempatando pela ordem da coluna (TEL1_TRA > TEL2_TRA > CFO1_TRA).
function selecionarMelhorTelefoneBR(tel1, tel2, cfo1) {
  const colunasBrutas = [tel1, tel2, cfo1];
  const candidatos = [];

  colunasBrutas.forEach((valorColuna, idxCol) => {
    const textoCol = String(valorColuna || '').trim();
    if (!textoCol) return;
    // Caso haja mais de um número separado por '/', ';' ou '|' no mesmo campo
    const trechos = textoCol.split(/[/;|]+/).map(t => t.trim()).filter(Boolean);
    trechos.forEach((trecho, idxTrecho) => {
      const analise = analisarCandidatoTelefone(trecho, idxCol + 1, idxTrecho);
      if (analise) candidatos.push(analise);
    });
  });

  if (candidatos.length === 0) {
    return {
      valido: false,
      original: '',
      e164: '',
      motivo: 'TEL1_TRA_AUSENTE_NA_ERP_PARCEIROS'
    };
  }

  const validos = candidatos
    .filter(c => c.valido)
    .sort((a, b) => {
      if (a.tier !== b.tier) return a.tier - b.tier;
      if (a.ordemColuna !== b.ordemColuna) return a.ordemColuna - b.ordemColuna;
      return a.indiceTrecho - b.indiceTrecho;
    });

  if (validos.length > 0) {
    const vencedor = validos[0];
    return {
      valido: true,
      original: vencedor.original,
      e164: vencedor.e164,
      motivo: null
    };
  }

  // Se nenhum for válido nas 3 colunas, retorna o primeiro valor preenchido que falhou
  const primeiroInvalido = candidatos[0];
  return {
    valido: false,
    original: primeiroInvalido.original,
    e164: primeiroInvalido.e164,
    motivo: primeiroInvalido.motivo
  };
}

// 2. Executar Alocação Cronológica (FIFO por VENC_REC) e verificar elegibilidade D-10 / D-5 + Repescagem hoje
const resultadoConsolidado = [];
const agendaJanelaAnalisada = [];
const dtHojeUTC = parseISODateUTC(dataHojeISO);

for (const cli of carteiraPorCliente.values()) {
  const saldoGlobalCliente = Number((cli.total_debito_d - cli.total_credito_c).toFixed(2));

  // Regra 4: Se o saldo global do cliente já for Credor (C <= 0), não notifica nenhum vencimento
  if (saldoGlobalCliente <= 0) continue;

  // Ordenar os vencimentos de Débito (D) do mais próximo para o mais distante (FIFO)
  const vencimentosOrdenados = Array.from(cli.vencimentosMap.values()).sort((a, b) =>
    a.venc_rec_iso.localeCompare(b.venc_rec_iso)
  );

  let creditoDisponivelFIFO = cli.total_credito_c;

  for (const v of vencimentosOrdenados) {
    // Abate o crédito disponível neste vencimento (FIFO)
    const creditoAbatidoNesteVencimento = Number(
      Math.min(creditoDisponivelFIFO, v.valor_debito_bruto).toFixed(2)
    );
    const saldoResultanteVencimento = Number(
      (v.valor_debito_bruto - creditoAbatidoNesteVencimento).toFixed(2)
    );
    creditoDisponivelFIFO = Number(
      (creditoDisponivelFIFO - creditoAbatidoNesteVencimento).toFixed(2)
    );

    // Se o crédito cobriu 100% deste vencimento (Saldo Credor/Zero no vencimento), não notifica
    if (saldoResultanteVencimento <= 0) continue;

    // Verifica se este vencimento tem notificação D-10 ou D-5 prevista para HOJE (ou Repescagem Automática)
    const dataTeoricaD10 = addDaysUTC(v.dt_vencimento, -10);
    const dataUtilD10 = ajustarParaDiaUtilAnterior(dataTeoricaD10);

    const dataTeoricaD5 = addDaysUTC(v.dt_vencimento, -5);
    const dataUtilD5 = ajustarParaDiaUtilAnterior(dataTeoricaD5);

    const diasAteVencimento = diffDaysUTC(v.dt_vencimento, dtHojeUTC);

    const chaveD10 = `${cli.codi_tra}_${v.venc_rec_iso}_D-10`;
    const chaveD5 = `${cli.codi_tra}_${v.venc_rec_iso}_D-5`;

    agendaJanelaAnalisada.push({
      codi_tra: cli.codi_tra,
      raza_tra: cli.raza_tra,
      codi_emp: cli.codi_emp,
      venc_rec_iso: v.venc_rec_iso,
      dias_ate_vencimento: diasAteVencimento,
      valor_bruto_vencimento: v.valor_debito_bruto,
      credito_abatido_fifo: creditoAbatidoNesteVencimento,
      saldo_devedor_resultante: saldoResultanteVencimento,
      disparo_d10_teorico: formatISODateUTC(dataTeoricaD10),
      disparo_d10_dia_util: dataUtilD10,
      disparo_d5_teorico: formatISODateUTC(dataTeoricaD5),
      disparo_d5_dia_util: dataUtilD5,
      repescagem_d10_pendente: chavesParaRepescagem.has(chaveD10),
      repescagem_d5_pendente: chavesParaRepescagem.has(chaveD5),
      data_execucao_avaliada: dataHojeISO
    });

    let etapaHoje = null;
    let dataNotificacaoTeorica = null;
    let houveAntecipacaoDiaUtil = false;
    let ehRepescagem = false;
    let infoRepescagem = null;

    if (dataUtilD10 === dataHojeISO) {
      etapaHoje = 'D-10';
      dataNotificacaoTeorica = formatISODateUTC(dataTeoricaD10);
      houveAntecipacaoDiaUtil = dataUtilD10 !== dataNotificacaoTeorica;
      if (chavesParaRepescagem.has(chaveD10)) {
        ehRepescagem = true;
        infoRepescagem = chavesParaRepescagem.get(chaveD10);
      }
    } else if (dataUtilD5 === dataHojeISO) {
      etapaHoje = 'D-5';
      dataNotificacaoTeorica = formatISODateUTC(dataTeoricaD5);
      houveAntecipacaoDiaUtil = dataUtilD5 !== dataNotificacaoTeorica;
      if (chavesParaRepescagem.has(chaveD5)) {
        ehRepescagem = true;
        infoRepescagem = chavesParaRepescagem.get(chaveD5);
      }
    } else if (
      dataHojeISO > dataUtilD5 &&
      dataHojeISO < v.venc_rec_iso &&
      !chavesJaEnviadas.has(chaveD5) &&
      chavesParaRepescagem.has(chaveD5)
    ) {
      // Repescagem automática do D-5 (dias úteis entre D-5 e a véspera do vencimento D-1)
      etapaHoje = 'D-5';
      infoRepescagem = chavesParaRepescagem.get(chaveD5);
      dataNotificacaoTeorica = infoRepescagem?.dtnt_cobr || formatISODateUTC(dataTeoricaD5);
      houveAntecipacaoDiaUtil = dataUtilD5 !== formatISODateUTC(dataTeoricaD5);
      ehRepescagem = true;
    } else if (
      dataHojeISO > dataUtilD10 &&
      dataHojeISO < dataUtilD5 &&
      !chavesJaEnviadas.has(chaveD10) &&
      chavesParaRepescagem.has(chaveD10)
    ) {
      // Repescagem automática do D-10 (dias úteis entre D-10 e a véspera da janela do D-5)
      etapaHoje = 'D-10';
      infoRepescagem = chavesParaRepescagem.get(chaveD10);
      dataNotificacaoTeorica = infoRepescagem?.dtnt_cobr || formatISODateUTC(dataTeoricaD10);
      houveAntecipacaoDiaUtil = dataUtilD10 !== formatISODateUTC(dataTeoricaD10);
      ehRepescagem = true;
    } else if (modoTesteForcarJanela) {
      etapaHoje = diasAteVencimento <= 7 ? 'D-5' : 'D-10';
      dataNotificacaoTeorica = etapaHoje === 'D-5' ? formatISODateUTC(dataTeoricaD5) : formatISODateUTC(dataTeoricaD10);
      houveAntecipacaoDiaUtil = false;
    }

    if (!etapaHoje) continue;

    const chaveGrupo = `${cli.codi_tra}_${v.venc_rec_iso}_${etapaHoje}`;

    // Regra 6: Evitar notificações duplicadas para o mesmo cliente, vencimento e etapa já ENVIADOS
    if (chavesJaEnviadas.has(chaveGrupo)) continue;

    const vencAnterior = ultimoVencimentoPorClienteEtapa.get(`${cli.codi_tra}_${etapaHoje}`) || null;
    // Só caracteriza prorrogação real se o vencimento anterior (futuro) deixou de existir em aberto e foi postergado
    const houveProrrogacao = Boolean(
      vencAnterior &&
      vencAnterior >= dataHojeISO &&
      !cli.vencimentosMap.has(vencAnterior) &&
      v.venc_rec_iso > vencAnterior
    );

    const valorFormatado = formatarMoedaBR(saldoResultanteVencimento);
    const dataVencimentoBR = formatarDataBR(v.venc_rec_iso);
    const validacaoFone = selecionarMelhorTelefoneBR(cli.tel1_tra, cli.tel2_tra, cli.cfo1_tra);
    const numeroTentativa = ehRepescagem ? (Number(infoRepescagem?.tent_cobr || 1) + 1) : 1;

    // Regra 5: Mensagem Padrão informando o Saldo Devedor Resultante do vencimento
    const mensagemPadrao = [
      `Olá, ${cli.raza_tra}, tudo bem?`,
      `Passando para lembrar que temos um pagamento no valor de R$ ${valorFormatado}, com vencimento em ${dataVencimentoBR}.`,
      `Gostaria de confirmar se está tudo certo para o pagamento na data prevista.`,
      `Caso precise do boleto ou de alguma informação para realizar o pagamento, por favor, entre em contato com ${config.telefone_contato_financeiro || '(00) 90000-0000'} que providenciaremos o encaminhamento.`,
      `Após a quitação, pedimos, se possível, o envio do comprovante para realizarmos a baixa.`,
      `Obrigada!`
    ].join('\n\n');

    resultadoConsolidado.push({
      json: {
        chave_idempotencia: chaveGrupo,
        possui_notificacoes_hoje: true,
        codi_tra: cli.codi_tra,
        raza_tra: cli.raza_tra,
        codi_emp: cli.codi_emp,
        tel1_tra_original: validacaoFone.original,
        venc_rec_iso: v.venc_rec_iso,
        venc_rec_br: dataVencimentoBR,
        etapa_notificacao: etapaHoje,
        data_notificacao_teorica: dataNotificacaoTeorica,
        data_notificacao_efetiva: dataHojeISO,
        antecipado_dia_util: houveAntecipacaoDiaUtil,
        repescagem_automatica: ehRepescagem,
        tentativa_numero: numeroTentativa,
        status_anterior_repescagem: ehRepescagem ? (infoRepescagem?.stat_cobr || null) : null,
        recalculado_por_prorrogacao: houveProrrogacao,
        vencimento_anterior_iso: houveProrrogacao ? vencAnterior : null,
        quantidade_titulos: v.quantidade_titulos,
        valor_bruto_vencimento: v.valor_debito_bruto,
        credito_abatido_vencimento: creditoAbatidoNesteVencimento,
        valor_consolidado: saldoResultanteVencimento,
        valor_consolidado_br: valorFormatado,
        saldo_debito_d: cli.total_debito_d,
        saldo_credito_c: cli.total_credito_c,
        saldo_compensado_cliente: saldoGlobalCliente,
        natureza_saldo: 'D',
        telefone_e164: validacaoFone.e164,
        cadastro_telefone_valido: validacaoFone.valido,
        motivo_invalidez_cadastro: validacaoFone.motivo,
        mensagem_texto: mensagemPadrao
      }
    });
  }
}

if (resultadoConsolidado.length === 0) {
  return [
    {
      json: {
        chave_idempotencia: '',
        possui_notificacoes_hoje: false,
        data_execucao_iso: dataHojeISO,
        total_lancamentos_oracle_janela: lancamentosRaw.length,
        total_clientes_avaliados: carteiraPorCliente.size,
        motivo_sem_disparo_hoje: `Existem ${agendaJanelaAnalisada.length} vencimento(s) com saldo devedor na janela de 1 a 18 dias, porém nenhum possui etapa D-10, D-5 ou Repescagem Automática prevista para a data de referência (${dataHojeISO}). Consulte 'agenda_proximos_disparos' para ver a data exata do D-10 e D-5 de cada cliente (ou ajuste 'data_simulacao_iso' / 'modo_teste_forcar_janela' no nó [02. Parâmetros Globais] para testar o envio).`,
        agenda_proximos_disparos: agendaJanelaAnalisada
      }
    }
  ];
}

return resultadoConsolidado;

