// Classifica o resultado da validação e do disparo Z-API em:
// - ENVIADO (possui WhatsApp confirmado no /phone-exists e envio aceito no /send-text com zaapId/messageId)
// - SEM_WHATSAPP (formato de telefone válido, porém /phone-exists retornou exists: false — ex: fixo sem WhatsApp)
// - NAO_ENTREGUE (erro técnico da Z-API, falha de conexão ou rejeição no envio)
// - PENDENTE (TEL1_TRA com formato inválido ou ausente na tabela ERP_PARCEIROS)

const dadosCliente = $('13. Lote Individual').first().json;
const payloadEntrada = $input.first()?.json || {};
const sufixoRepescagem = dadosCliente.repescagem_automatica
  ? ` [Repescagem automática - ${dadosCliente.tentativa_numero || 2}ª tentativa | Status anterior: ${dadosCliente.status_anterior_repescagem || 'PENDENTE'}]`
  : '';

let statusEnvio = 'ENVIADO';
let codigoErro = null;
let detalheStatus = `Mensagem enviada com sucesso via Z-API (WhatsApp validado previamente via phone-exists).${sufixoRepescagem}`;
let telefoneE164Final = dadosCliente.telefone_e164;
let respostaBrutaAuditoria = payloadEntrada;

if (!dadosCliente.cadastro_telefone_valido) {
  // 1. Formato inválido ou ausente na ERP_PARCEIROS (nem consultou Z-API)
  statusEnvio = 'PENDENTE';
  codigoErro = dadosCliente.motivo_invalidez_cadastro || 'TEL1_TRA_INVALIDO';
  detalheStatus = `Envio pendente por inconsistência cadastral na ERP_PARCEIROS.TEL1_TRA: ${codigoErro} (Valor atual: "${dadosCliente.tel1_tra_original || 'VAZIO'}").${sufixoRepescagem}`;
  respostaBrutaAuditoria = { envio_ignorado: true, motivo: codigoErro, repescagem_automatica: Boolean(dadosCliente.repescagem_automatica) };
} else if (
  !payloadEntrada.error &&
  !(payloadEntrada.statusCode >= 400) &&
  Object.prototype.hasOwnProperty.call(payloadEntrada, 'exists') &&
  payloadEntrada.exists !== true
) {
  // 2. Veio da saída 'false' do [14c. Possui WhatsApp?] com retorno explícito exists: false (sem erro de conexão/API)
  statusEnvio = 'SEM_WHATSAPP';
  codigoErro = 'NUMERO_SEM_WHATSAPP';
  detalheStatus = `O telefone cadastrado na ERP_PARCEIROS ("${dadosCliente.tel1_tra_original || ''}" -> ${dadosCliente.telefone_e164}) não possui conta ativa no WhatsApp (telefone fixo ou número sem WhatsApp). Necessário atualizar o telefone na tabela ERP_PARCEIROS.${sufixoRepescagem}`;
} else {
  // 3. Caso tenha passado pelo [14b. Verificar WhatsApp] (ou falhado tecnicamente nele/no [15. Enviar WhatsApp])
  const checkWpp = $('14b. Verificar WhatsApp').first()?.json || {};
  if (checkWpp.phone && typeof checkWpp.phone === 'string') {
    telefoneE164Final = checkWpp.phone;
  }

  if (
    payloadEntrada.error ||
    payloadEntrada.statusCode >= 400 ||
    payloadEntrada.value === false ||
    (!payloadEntrada.zaapId && !payloadEntrada.messageId && !payloadEntrada.id)
  ) {
    statusEnvio = 'NAO_ENTREGUE';
    codigoErro = String(payloadEntrada.code || payloadEntrada.statusCode || 'FALHA_ENTREGA_ZAPI');
    detalheStatus = `${String(
      payloadEntrada.message ||
      payloadEntrada.error?.message ||
      payloadEntrada.error ||
      'Falha técnica ao consultar/enviar mensagem na Z-API. Verificar conexão da instância.'
    )}${sufixoRepescagem}`;
  }
}

return [
  {
    json: {
      ...dadosCliente,
      telefone_e164: telefoneE164Final,
      status_envio: statusEnvio,
      codigo_erro: codigoErro,
      detalhe_status: detalheStatus,
      zapi_message_id: statusEnvio === 'ENVIADO' ? (payloadEntrada.messageId || payloadEntrada.zaapId || payloadEntrada.id || null) : null,
      zapi_raw_response: respostaBrutaAuditoria,
      data_hora_processamento: new Date().toISOString()
    }
  }
];

// Restaura o payload completo do item processado na iteração atual
// para que o SplitInBatches acumule todos os objetos na saída 'done' (Output 0).
return $('16. Classificar Status').all();

// ============================================================================
// REGRA 6: RELATÓRIO E CONTROLE (E-MAIL PADRONIZADO CORPORATIVO + PLANILHA EXCEL)
// 1. Agrupa, classifica e ordena todos os registros processados na execução.
// 2. Calcula os indicadores do resumo (Enviadas, Sem WhatsApp, Formato Inválido/Vazio, Não Entregues).
// 3. Monta o HTML institucional Empresa Exemplo e prepara as linhas padronizadas
//    para geração do arquivo Excel (.xlsx) anexo.
// ============================================================================

const todosProcessados = $input.all().map(i => i.json).filter(x => x && x.chave_idempotencia);
const config = $('02. Parâmetros Globais').first().json;
const dataExecucao = $('04. Validar Calendário').first().json.data_execucao_iso;

function formatarDataBR(isoStr) {
  const clean = String(isoStr || '').slice(0, 10);
  const partes = clean.split('-');
  if (partes.length !== 3) return clean;
  return `${partes[2]}/${partes[1]}/${partes[0]}`;
}

function normalizarListaEmail(valorBruto) {
  if (Array.isArray(valorBruto)) return valorBruto;
  if (typeof valorBruto === 'string' && valorBruto.trim()) {
    try {
      const parsed = JSON.parse(valorBruto);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
}

const dataExecucaoBR = formatarDataBR(dataExecucao);
const anoExecucao = String(dataExecucao || '').slice(0, 4) || String(new Date().getFullYear());

const listaDestinatarios = normalizarListaEmail(config.destinatarios_relatorio_email);
const destinatariosNomes = listaDestinatarios
  .map(d => d?.nome)
  .filter(Boolean);
const destinatariosEmails = listaDestinatarios
  .map(d => d?.email)
  .filter(Boolean)
  .join(', ');

const listaCopias = normalizarListaEmail(config.copias_relatorio_email);
const copiasNomes = listaCopias
  .map(d => d?.nome)
  .filter(Boolean);
const copiasEmails = listaCopias
  .map(d => d?.email)
  .filter(Boolean)
  .join(', ');

const enviadas = todosProcessados.filter(x => x.status_envio === 'ENVIADO' || x.status_envio === 'ENVIADA');
const semWhatsapp = todosProcessados.filter(x => x.status_envio === 'SEM_WHATSAPP');
const pendentes = todosProcessados.filter(x => x.status_envio === 'PENDENTE');
const naoEntregues = todosProcessados.filter(x => x.status_envio === 'NAO_ENTREGUE');
const falhasEPendencias = [...semWhatsapp, ...pendentes, ...naoEntregues];

// Ordena todos os registros para a planilha Excel:
// 1º SEM_WHATSAPP -> 2º PENDENTE -> 3º NAO_ENTREGUE -> 4º ENVIADO
const pesoStatus = {
  SEM_WHATSAPP: 1,
  PENDENTE: 2,
  NAO_ENTREGUE: 3,
  ENVIADO: 4,
  ENVIADA: 4
};

const registrosOrdenados = [...todosProcessados].sort((a, b) => {
  const pA = pesoStatus[a.status_envio] ?? 9;
  const pB = pesoStatus[b.status_envio] ?? 9;
  if (pA !== pB) return pA - pB;
  const cmpVenc = String(a.venc_rec_iso || '').localeCompare(String(b.venc_rec_iso || ''));
  if (cmpVenc !== 0) return cmpVenc;
  return String(a.raza_tra || '').localeCompare(String(b.raza_tra || ''));
});

const linhasExcelPadronizadas = registrosOrdenados.map(item => ({
  "Loja (CODI_EMP)": item.codi_emp !== null && item.codi_emp !== undefined && item.codi_emp !== '' ? Number(item.codi_emp) : '-',
  "CODI_TRA": Number(item.codi_tra),
  "Cliente (RAZA_TRA)": item.raza_tra || '',
  "Status": item.status_envio || '',
  "Repescagem Automática?": item.repescagem_automatica ? `Sim (${item.tentativa_numero || 2}ª tentativa | Antes: ${item.status_anterior_repescagem || 'PENDENTE'})` : 'Não',
  "Tentativa Nº": Number(item.tentativa_numero || 1),
  "Telefone Cadastrado (ERP_PARCEIROS)": item.tel1_tra_original || 'VAZIO',
  "Telefone Padronizado (WhatsApp)": item.telefone_e164 || '-',
  "Etapa": item.etapa_notificacao || '',
  "Vencimento (VENC_REC)": item.venc_rec_br || formatarDataBR(item.venc_rec_iso),
  "Qtd. Títulos": Number(item.quantidade_titulos || 1),
  "Valor Bruto Vencimento (R$)": Number(item.valor_bruto_vencimento || 0),
  "Crédito Abatido FIFO (R$)": Number(item.credito_abatido_vencimento || 0),
  "Saldo Devedor Resultante (R$)": Number(item.valor_consolidado || 0),
  "Saldo Devedor Formatado": `R$ ${item.valor_consolidado_br || '0,00'}`,
  "Data Prevista Notificação": formatarDataBR(item.data_notificacao_teorica),
  "Data Efetiva Execução": formatarDataBR(item.data_notificacao_teorica ? item.data_notificacao_efetiva : dataExecucao),
  "Antecipado Dia Útil?": item.antecipado_dia_util ? 'Sim' : 'Não',
  "Prorrogação Detectada?": item.recalculado_por_prorrogacao ? 'Sim' : 'Não',
  "Motivo / Diagnóstico": item.detalhe_status || '',
  "Código de Erro": item.codigo_erro || '-',
  "ID Mensagem Z-API": item.zapi_message_id || '-'
}));

